    tricks = [tuple(map(float, input().split())) for _ in range(m)]

    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + 1

        for t, p, d in tricks:
            if t > i:
                break
            if i == t:
                dp[i] = min(dp[i], dp[t - 1] + d * (1 - p))
            else:
                dp[i] = min(dp[i], dp[t - 1] + d * (1 - p) + dp[i - t])

